const cfg = $('Config').first().json;
if (!cfg.instance_name || !cfg.group_jid) {
  throw new Error('Config incompleta: preencha group_jid (JID do grupo, termina em @g.us) no nó "Config".');
}
const r = $input.first().json;
// Primeira execução: o nó anterior acabou de gravar o ponto de partida na tabela notif_cursores.
// Não avisa o histórico inteiro.
if (Number(r.iniciou_agora) > 0) return [];
return [{ json: { chat: Number(r.chat), rel: Number(r.rel), bid: Number(r.bid), deals_desde: r.deals_desde } }];

const limpo = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
const tel = (d) => {
  const n = String(d || '').replace(/\D/g, '');
  if (!n) return 'sem telefone';
  const l = n.startsWith('55') && n.length >= 12 ? n.slice(2) : n;
  return l.length === 11 ? '+55 (' + l.slice(0, 2) + ') ' + l.slice(2, 7) + '-' + l.slice(7)
       : l.length === 10 ? '+55 (' + l.slice(0, 2) + ') ' + l.slice(2, 6) + '-' + l.slice(6) : '+' + n;
};
const pessoa = (rotulo, p) => {
  p = p || {};
  return rotulo + ': ' + (limpo(p.nome) || 'sem nome') + ' · id ' + (p.id == null ? '?' : p.id) +
    '\n   ✉ ' + (limpo(p.email) || 'sem e-mail') + ' · 📞 ' + tel(p.telefone);
};
const cfg = $('Config').first().json;
// A consulta já veio sem o que foi avisado (tabela notif_enviadas).
const linhas = $input.all().map((i) => i.json).filter((r) => r && r.tipo);
const chave = (r) => r.tipo + ':' + r.ref_id;
const brl = (n) => 'R$ ' + Number(n).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

function texto(r) {
  const d = r.dados || {};
  const prod = limpo(d.produto) || 'produto não informado';
  switch (r.tipo) {
    case 'chat':
      return '💬 *Novo chat iniciado*\nProduto: ' + prod + ' (anúncio #' + d.bid_id + ')\nPrimeira mensagem de: ' +
        (d.quem_enviou === 'anunciante' ? 'anunciante' : 'interessado') + '\n' +
        pessoa('👤 Interessado', d.interessado) + '\n' + pessoa('🏷 Anunciante', d.anunciante);
    case 'contato':
      return '🔓 *Contato liberado*\n' + (limpo(d.quem) || 'Um usuário') + ' liberou o contato de ' +
        (limpo(d.dono) || 'um anunciante') + '\nProduto: ' + prod + ' (anúncio #' + d.bid_id + ')';
    case 'anuncio': {
      const preco = Number(d.preco) > 0 ? brl(d.preco) : 'a combinar';
      return '📢 *Novo anúncio*\n' + (limpo(d.quem) || 'Um usuário') + ' anunciou (' + (limpo(d.operacao).toLowerCase() || 'oferta') + '): ' + prod +
        '\nQuantidade: ' + (limpo(d.quantidade) || '—') + ' · Preço: ' + preco + (d.uf ? ' · ' + d.uf : '') + ' (anúncio #' + r.ref_id + ')';
    }
    case 'venda':
      return '💰 *Venda fechada*\nProduto: ' + prod + ' (anúncio #' + d.bid_id + ')\n' + (limpo(d.dono) || 'Anunciante') + ' ⇄ ' +
        (limpo(d.outra_parte) || 'outra parte') + '\nQuantidade: ' + (limpo(d.quantidade) || '—') + ' · Preço: ' + (Number(d.preco) > 0 ? brl(d.preco) : 'a combinar');
    default:
      return null;
  }
}

const limite = Number(cfg.max_por_execucao) || 10;
const out = linhas.slice(0, limite).map((r) => ({ json: { key: chave(r), text: texto(r) } })).filter((i) => i.json.text);
const resto = linhas.slice(limite);
if (resto.length) {
  const por = resto.reduce((o, r) => ((o[r.tipo] = (o[r.tipo] || 0) + 1), o), {});
  const nomes = { chat: 'chats', contato: 'contatos liberados', anuncio: 'anúncios', venda: 'vendas' };
  // as chaves dos não detalhados são registradas junto com o resumo, para não repetir depois
  out.push({ json: { key: null, extra_keys: resto.map(chave), text: '⚠️ Mais ' + resto.length + ' eventos nesta rodada, não detalhados: ' +
    Object.entries(por).map(([t, n]) => n + ' ' + nomes[t]).join(', ') + '.' } });
}
return out;

const msgs = $('Monta mensagens').all();
const res = $('Envia no grupo').all();
const est = $('Estado').first().json;
const chaves = [];
let falhas = 0;
res.forEach((r, i) => {
  const falhou = !r.json || r.json.error || r.json.success === false;
  if (falhou) { falhas++; return; }
  const m = msgs[i] && msgs[i].json;
  if (!m) return;
  if (m.key) chaves.push(m.key);
  (m.extra_keys || []).forEach((k) => chaves.push(k));
});
// Os cursores só avançam se TODAS as mensagens saíram; as que saíram ficam registradas de qualquer forma.
const linhas = $('Eventos novos').all().map((i) => i.json).filter((r) => r && r.tipo);
const max = (tipo, base) => {
  const ids = linhas.filter((r) => r.tipo === tipo).map((r) => Number(r.ref_id));
  return ids.length ? Math.max(base, ...ids) : base;
};
const ts = linhas.filter((r) => r.tipo === 'venda').map((r) => r.ts).sort();
const ultimaVenda = ts.length && ts[ts.length - 1] > est.deals_desde ? ts[ts.length - 1] : est.deals_desde;
return [{ json: { chaves, todos_ok: falhas === 0, falhas, chat: max('chat', est.chat), rel: max('contato', est.rel), bid: max('anuncio', est.bid), deals_desde: ultimaVenda } }];

